--
-- Table structure for table `task`
--

DROP TABLE IF EXISTS `task`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `task` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '任务主键，前端轮询、取消、日志弹窗都用这个 id',
  `类型` varchar(50) NOT NULL COMMENT '【M3】任务种类，后端白名单 23 种：文本回复/图片解析/文生图/生成图片/编辑图片单图/编辑图片三图/三图编辑一致版/多图编辑多人合并版/文生图8K/动漫转真人/首尾帧/文生视频/参考生视频/多参考生视频/首尾帧生视频/加速版生视频/外部分组图生视频/外部分组多参考生视频/二采重绘/二采加速生视频/去水印/资产提取/分镜拆分',
  `状态` varchar(20) NOT NULL DEFAULT '已创建' COMMENT '执行状态：已创建/已提交/排队中/生成中/成功/失败/中断/已取消',
  `创建人id` bigint(20) NOT NULL COMMENT '提交该任务的用户',
  `comfy_prompt_id` varchar(64) DEFAULT NULL COMMENT '提交到 Comfy 成功后返回的 prompt_id；LLM 测试为空',
  `日志路径` varchar(512) DEFAULT NULL COMMENT '相对 backend/资源/日志/ 的日志文件路径，日志弹窗按任务 id 读',
  `正向提示词` text DEFAULT NULL COMMENT '前端提交、前端展示、实际发给模型的完整正向提示词，后端禁止再拼接后覆盖',
  `反向提示词` text DEFAULT NULL COMMENT '前端提交的完整反向提示词；LLM 无反向可空',
  `图片宽` int(11) DEFAULT NULL COMMENT '出图像素宽度；非出图任务可空',
  `图片高` int(11) DEFAULT NULL COMMENT '出图像素高度；非出图任务可空',
  `视频宽` int(11) DEFAULT NULL COMMENT '视频像素宽度；非视频任务可空',
  `视频高` int(11) DEFAULT NULL COMMENT '视频像素高度；非视频任务可空',
  `一采MP` decimal(6,2) DEFAULT NULL COMMENT '视频采样分辨率，单位兆像素。非二采视频任务只填这一列；二采任务填一采档。非视频任务可空',
  `二采MP` decimal(6,2) DEFAULT NULL COMMENT '二采档采样分辨率，单位兆像素。仅二采任务填写；其它任务必须空。禁止一列兼存两个 MP',
  `cfg` decimal(6,2) DEFAULT NULL COMMENT 'MiniMax H3 Director 的 cfg 值；仅导演台系列工作流填写，其它任务可空',
  `seed` bigint(20) DEFAULT NULL COMMENT '随机种子。页上要测就必须能提交、能落库；不测的类型可空',
  `水印` varchar(50) DEFAULT NULL COMMENT '去水印测试的水印类型或标识；非去水印任务可空',
  `系统提示词` text DEFAULT NULL COMMENT 'LLM 文本/识图测试的完整系统提示词，前端提交完整、后端禁止拼接；Comfy 任务可空',
  `组1提示词` text DEFAULT NULL COMMENT '外部分组第1组提示词',
  `组2提示词` text DEFAULT NULL COMMENT '外部分组第2组提示词',
  `组3提示词` text DEFAULT NULL COMMENT '外部分组第3组提示词',
  `组4提示词` text DEFAULT NULL COMMENT '外部分组第4组提示词',
  `组1时长` decimal(10,2) DEFAULT NULL COMMENT '外部分组第1组秒数',
  `组2时长` decimal(10,2) DEFAULT NULL COMMENT '外部分组第2组秒数',
  `组3时长` decimal(10,2) DEFAULT NULL COMMENT '外部分组第3组秒数',
  `组4时长` decimal(10,2) DEFAULT NULL COMMENT '外部分组第4组秒数',
  `输入图1` varchar(512) DEFAULT NULL COMMENT '输入/参考图片1，相对 backend/资源/上传/ 的路径；最多 9 张，无则空',
  `输入图2` varchar(512) DEFAULT NULL COMMENT '输入/参考图片2，相对 backend/资源/上传/ 的路径；最多 9 张，无则空',
  `输入图3` varchar(512) DEFAULT NULL COMMENT '输入/参考图片3，相对 backend/资源/上传/ 的路径；最多 9 张，无则空',
  `输入图4` varchar(512) DEFAULT NULL COMMENT '输入/参考图片4，相对 backend/资源/上传/ 的路径；最多 9 张，无则空',
  `输入图5` varchar(512) DEFAULT NULL COMMENT '输入/参考图片5，相对 backend/资源/上传/ 的路径；最多 9 张，无则空',
  `输入图6` varchar(512) DEFAULT NULL COMMENT '输入/参考图片6，相对 backend/资源/上传/ 的路径；最多 9 张，无则空',
  `输入图7` varchar(512) DEFAULT NULL COMMENT '输入/参考图片7，相对 backend/资源/上传/ 的路径；最多 9 张，无则空',
  `输入图8` varchar(512) DEFAULT NULL COMMENT '输入/参考图片8，相对 backend/资源/上传/ 的路径；最多 9 张，无则空',
  `输入图9` varchar(512) DEFAULT NULL COMMENT '输入/参考图片9，相对 backend/资源/上传/ 的路径；最多 9 张，无则空',
  `输入视频1` varchar(512) DEFAULT NULL COMMENT '输入视频1，相对 backend/资源/上传/ 的路径；最多 3 个，无则空',
  `输入视频2` varchar(512) DEFAULT NULL COMMENT '输入视频2，相对 backend/资源/上传/ 的路径；最多 3 个，无则空',
  `输入视频3` varchar(512) DEFAULT NULL COMMENT '输入视频3，相对 backend/资源/上传/ 的路径；最多 3 个，无则空',
  `输入音频1` varchar(512) DEFAULT NULL COMMENT '输入音频1，相对 backend/资源/上传/ 的路径；最多 3 个，无则空',
  `输入音频2` varchar(512) DEFAULT NULL COMMENT '输入音频2，相对 backend/资源/上传/ 的路径；最多 3 个，无则空',
  `输入音频3` varchar(512) DEFAULT NULL COMMENT '输入音频3，相对 backend/资源/上传/ 的路径；最多 3 个，无则空',
  `回复` text DEFAULT NULL COMMENT 'LLM 返回正文；Comfy 任务为空',
  `产物图片` varchar(512) DEFAULT NULL COMMENT '成功时产出的图片路径，相对 backend/资源/产物/；最多 1 张，禁止与产物视频同时有值',
  `产物视频1` varchar(512) DEFAULT NULL COMMENT '成功时产出的第 1 个视频路径，相对 backend/资源/产物/；与产物图片互斥',
  `产物视频2` varchar(512) DEFAULT NULL COMMENT '成功时产出的第 2 个视频路径；仅一次返 2 个视频的任务填',
  `错误信息` text DEFAULT NULL COMMENT '失败、中断或取消时的异常信息',
  `错误文件` varchar(512) DEFAULT NULL COMMENT '失败时出错的 py 文件真实路径',
  `错误行号` int(11) DEFAULT NULL COMMENT '失败时出错的行号',
  `错误函数` varchar(100) DEFAULT NULL COMMENT '失败时出错的函数名',
  `创建时间` datetime(6) NOT NULL DEFAULT current_timestamp(6) COMMENT '任务在本平台创建的时间',
  `开始时间` datetime(6) DEFAULT NULL COMMENT 'ComfyUI 真正开始跑该任务的时间；排队中必须为空',
  `结束时间` datetime(6) DEFAULT NULL COMMENT '进入成功、失败、中断或已取消的时间',
  `比例` varchar(16) DEFAULT NULL COMMENT '视频宽高比标签键（如 16:9 / 9:16 / 1:1 / 4:3 等），提交侧透传，后端映射为 Comfy 完整标签写 ResolutionSelector；仅参考生视频填写（二采不含比例）；非视频任务可空',
  `视频时长` decimal(6,2) DEFAULT NULL COMMENT '请求的视频生成时长（秒），写入 Comfy PrimitiveFloat 时长节点；参考生视频默认 5，二采默认 7；非视频任务可空',
  `产物图片2` varchar(512) DEFAULT NULL COMMENT '成功时产出的第 2 张图片路径，相对 backend/资源/产物/；目前仅文生图8K 使用（产物图片=1x 原尺寸，产物图片2=4x 放大）',
  `模式` varchar(16) DEFAULT NULL COMMENT '导演台全能生成模式：t2v=文生视频 / i2v=图生视频 / fl2v=首尾帧 / r2v=参考主体 / v2v=视频转视频 / rv2v=参考改视频；后端按此自动切换底膜 ref2va↔fl2va',
  `生成声音` tinyint(1) DEFAULT NULL COMMENT '是否生成声音：1=生成(generate) / 0=静音(mute)；NULL 后端按 1 处理，写 Director output.audioMode',
  `步数` int(11) DEFAULT NULL COMMENT '采样步数，写 Director 节点 steps（默认 8，Turbo 8step LoRA 下用 8）',
  `采样器` varchar(50) DEFAULT NULL COMMENT '采样器名，写 Director 节点 sampler（如 res_multistep）；NULL 走工作流默认',
  `底膜精度` varchar(8) DEFAULT NULL COMMENT '导演台全能的底膜精度开关：auto=工作流默认(ref2va bf16/fl2va int8) / bf16=两个族都bf16 / int8=两个族都int8 convrot',
  `request_id` varchar(64) DEFAULT NULL COMMENT '【M2】幂等键：同 创建人id+request_id 重复提交返回原任务（uk_task_幂等）；存量任务可空',
  `进度` tinyint(4) DEFAULT NULL COMMENT '【M2】执行进度 0~100；NULL=该类型不支持进度',
  `积分` decimal(10,2) DEFAULT NULL COMMENT '【M2】本任务积分消耗；提交预扣→成功落账/失败回退（流水见 积分流水 表）；NULL=免费',
  `重试次数` int(11) NOT NULL DEFAULT 0 COMMENT '【M2】失败自动重试次数，上限 3（指数退避）',
  `页面来源` varchar(64) DEFAULT NULL COMMENT '【M2】提交页面路由，如 /video/shot；按页聚合统计与权限校验',
  `业务实体` varchar(128) DEFAULT NULL COMMENT '【M2】关联业务实体，任务完成据此回写业务状态（契约 C5），如 1:1:SH002（剧:集:镜）或 CHAR_001（资产id）',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_task_幂等` (`创建人id`,`request_id`) USING BTREE COMMENT '【M2】同用户同 request_id 唯一，实现提交幂等',
  KEY `idx_task_状态` (`状态`) USING BTREE,
  KEY `idx_task_创建人id` (`创建人id`) USING BTREE,
  KEY `idx_task_类型` (`类型`) USING BTREE,
  KEY `idx_task_创建时间` (`创建时间`) USING BTREE,
  KEY `idx_task_页面来源` (`页面来源`) USING BTREE,
  KEY `idx_task_业务实体` (`业务实体`) USING BTREE,
  CONSTRAINT `fk_task_创建人id` FOREIGN KEY (`创建人id`) REFERENCES `用户` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=181 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='所有测试/生成任务唯一管理表；任意时刻最多一条 Comfy 任务处于生成中';
/*!40101 SET character_set_client = @saved_cs_client */;

