--
-- Table structure for table `人物`
--

DROP TABLE IF EXISTS `人物`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `人物` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '行主键',
  `剧id` bigint(20) NOT NULL COMMENT '所属剧',
  `人物id` varchar(32) NOT NULL COMMENT '业务编号 CHAR_xxx，剧内唯一；/video/assets 人物分区按它对账',
  `名` varchar(50) NOT NULL COMMENT '人物名',
  `别名` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '别名数组，如 ["三班教室","教室"]' CHECK (json_valid(`别名`)),
  `性别` varchar(10) NOT NULL DEFAULT '男' COMMENT '男/女',
  `年龄档` varchar(20) DEFAULT NULL COMMENT '年龄档，如 青年/儿童/老年',
  `外观全文` text DEFAULT NULL COMMENT '可拍级外观描述（资产提取的原文来源）',
  `性格` text DEFAULT NULL COMMENT '性格要点',
  `关系` text DEFAULT NULL COMMENT '人物关系',
  `音色提示词` text DEFAULT NULL COMMENT '音色提示词，格式「性别，年龄档，音色 · 年龄，身份一句话」；非空校验（C3 音色前置的种子）',
  `基础版本` int(11) NOT NULL DEFAULT 1 COMMENT '【C9】乐观锁版本号',
  `创建时间` datetime(6) NOT NULL DEFAULT current_timestamp(6) COMMENT '创建时间',
  `更新时间` datetime(6) NOT NULL DEFAULT current_timestamp(6) ON UPDATE current_timestamp(6) COMMENT '最后更新时间',
  `简介` varchar(255) DEFAULT NULL COMMENT '一句话简介（卡片副题）',
  `分组` varchar(50) DEFAULT '本剧角色' COMMENT '卡片分组',
  `卡色` varchar(10) DEFAULT NULL COMMENT '卡片配色，如 #3b4a63',
  `身份` text DEFAULT NULL COMMENT '身份（可分段：第1-5集：…；第6集起：…）',
  `关系变化` text DEFAULT NULL COMMENT '与主角关系随集变化（可分段）',
  `态度` text DEFAULT NULL COMMENT '立场态度（可分段）',
  `外貌` text DEFAULT NULL COMMENT '外貌，能直接拿去画（可分段）',
  `身材` varchar(255) DEFAULT NULL COMMENT '身材',
  `穿搭` text DEFAULT NULL COMMENT '穿搭（可分段）',
  `身体情况` text DEFAULT NULL COMMENT '身体情况（可分段）',
  `情感情况` text DEFAULT NULL COMMENT '情感情况（可分段）',
  `精神情况` text DEFAULT NULL COMMENT '精神情况（可分段）',
  `当前状态` text DEFAULT NULL COMMENT '当前状态（可分段）',
  `当前姿势` varchar(255) DEFAULT NULL COMMENT '当前姿势（可分段）',
  `内心想法` text DEFAULT NULL COMMENT '内心想法（可分段）',
  `技能` text DEFAULT NULL COMMENT '角色技能（可分段）',
  `核心目标` text DEFAULT NULL COMMENT '核心目标（可分段）',
  `关系网` text DEFAULT NULL COMMENT '和谁是什么关系的概述',
  `背景故事` text DEFAULT NULL COMMENT '背景故事',
  `台词风格` varchar(255) DEFAULT NULL COMMENT '台词风格',
  `口头禅` varchar(255) DEFAULT NULL COMMENT '口头禅',
  `概括` varchar(500) DEFAULT NULL COMMENT '人物概括（下游页面浓缩版）',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_人物_剧内编号` (`剧id`,`人物id`) USING BTREE,
  CONSTRAINT `fk_人物_剧id` FOREIGN KEY (`剧id`) REFERENCES `剧` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=158 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='人物卡：外观/性格/关系/音色提示词';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `人物`
--

LOCK TABLES `人物` WRITE;
/*!40000 ALTER TABLE `人物` DISABLE KEYS */;
INSERT INTO `人物` VALUES
(143,1,'CHAR_001','风见苍',NULL,'男','28岁',NULL,'冷静克制，习惯用数据衡量战力，关键时刻会打破规则保护学生，对失败者有近乎苛刻的期待','主角',NULL,1,'2026-11-02 17:15:07.746718','2026-11-02 17:15:07.746718','忍校末位淘汰制执行者，表面冷酷实则护犊子的禁术教师','本剧角色','#3b4a63','忍校特别讲师，负责毕业班生死考核','他是毕业班七名学生的直接负责人，也是他们命运的裁决者','他站在规则与人性夹缝中，既想通过残酷筛选出最强忍者，又怕把学生逼疯','黑发利落背头，左眉有一道旧疤，眼神锐利如刀，肤色偏黑，常穿深蓝色立领衬衫配黑色战术裤，佩戴写有「禁术」字样的木牌','身材精瘦结实，肩宽腰窄，肌肉线条明显，右手食指戴一枚银色戒指','深蓝色立领衬衫，黑色战术长裤，黑色皮靴，腰间挂着忍具包和写有学生姓名的木牌，左臂缠着黑色绷带','身体健康，但左肩旧伤会在剧烈动作时隐痛，精神高度紧绷，对睡眠有轻微依赖','第1集起：在讲台上宣布末位淘汰规则，观察学生反应，内心盘算如何让他们快速成长；第2集：在训练场亲自示范禁术，眼神中流露出一丝不易察觉的温柔；第2集：在生死决战中站在学生身后，随时准备接住即将崩溃的人','站立于讲台中央，双手撑在桌沿，身体前倾，目光扫过全场；训练场上单手结印，另一只手虚握，模拟攻击姿态；决战时单膝跪地，一手撑地，一手伸向倒地的学生','他们以为我在折磨他们，其实我只是在教他们如何不死','精通「影分身之术」改良版、查克拉精密控制、战术预判','让七名学生全部活下来并突破极限，证明末位淘汰制并非无情','他是风见苍的导师，也是唯一知道苍过去失败经历的人；他是毕业班学生千羽的亲生父亲；他是忍校校长的旧友','曾是一名天才忍者，因一次任务失败导致队友全灭，从此坚信只有最强者才能生存，来到忍校寻找能继承自己意志的学生','台词简短有力，常用反问句，语气平淡但暗藏锋芒','「还活着吗？」「很好，再快一点」「这就是你的极限吗？」','一个用残酷手段锻造最强忍者的教师，表面冷酷内心炽热，在规则与羁绊间寻找平衡。','',''),
(144,1,'CHAR_002','千羽',NULL,'女','16岁',NULL,'敏感细腻，容易自我怀疑，但在关键时刻能爆发惊人潜力，对风见苍既敬畏又依赖','主角（学生）',NULL,1,'2026-11-02 17:15:07.746718','2026-11-02 17:15:07.746718','毕业班第一名，天赋极高却缺乏自信，被风见苍选中作为核心战力','本剧角色','#35435a','毕业班首席学生，风见苍的首席弟子','他是风见苍最器重的学生，也是他试图改变命运的关键','她站在天赋与努力的交叉点，既渴望被认可又害怕辜负期待','短发齐刘海，眼睛大而清澈，皮肤白皙，常穿白色忍服外套配黑色紧身衣，佩戴千羽族徽记','身材娇小玲珑，比例匀称，腿部线条优美，双手修长','白色忍服外套，黑色紧身内衬，黑色长筒袜，白色忍者鞋，腰间挂着储物卷轴，左耳戴着一枚银色羽毛耳饰','身体健康，但长期过度训练导致手腕有轻微劳损，精神压力较大，常因失眠而疲惫','第1集起：在考核中名列前茅，却因害怕失误而犹豫不决；第2集：在风见苍的指导下突破瓶颈，开始信任自己的直觉；第2集：在生死对决中觉醒禁术潜力，成为班级的灵魂人物','站立于训练场中央，双手握拳置于胸前，眼神坚定；突破时单腿站立，双手高举，查克拉环绕周身；决战时双膝跪地，双手撑地，额头抵地，浑身颤抖','我不够好，但我不能倒下，因为老师还在看着我','精通「千羽之舞」禁术、高速移动、查克拉爆发','成为真正的强者，不辜负风见苍的期望，证明自己的价值','她是风见苍的首席学生；她是忍校校长的孙女；她与第二名雪见是竞争对手兼挚友','千羽族后裔，天生查克拉亲和度高，却因家族期望过重而背负巨大压力，风见苍的出现让她看到了另一种可能','台词轻柔但坚定，常用肯定句，偶尔流露脆弱','「我听到了」「我会做到的」「老师，我还在」','一个天赋异禀却内心敏感的女孩，在残酷竞争中找回自我，从依赖到独立的蜕变过程。','',''),
(145,1,'CHAR_003','雪见',NULL,'男','17岁',NULL,'理性冷静，善于分析局势，但情感表达含蓄，对风见苍怀有复杂感激之情','配角（学生）',NULL,1,'2026-11-02 17:15:07.746718','2026-11-02 17:15:07.746718','毕业班第二名，实力均衡却缺乏爆发力，风见苍的重点调教对象','本剧角色','#3f4652','毕业班副首席，风见苍的二弟子','他是风见苍最信任的战术型学生，也是千羽的挚友','他站在理性与情感的边界，既想证明自己又不愿被定义为工具','短发微卷，眼睛狭长，皮肤微黑，常穿灰色忍服配深色护腕，佩戴雪见族徽记','身材中等偏瘦，肌肉线条流畅，反应敏捷','灰色忍服上衣，深色长裤，黑色护腕，黑色忍者鞋，腰间挂着战术匕首，右臂缠着灰色绷带','身体健康，但右膝有旧伤，精神稳定，善于自我调节','第1集起：在考核中稳扎稳打，注重团队协作；第2集：在风见苍的指导下学会冒险，开始展现个人特色；第2集：在生死对决中做出关键决策，拯救千羽','站立于训练场侧翼，双手抱胸，观察千羽的动作；突破时单腿跳跃，双手快速结印；决战时单膝跪地，一手持匕首，一手伸向千羽','理性不能解决所有问题，有时候需要赌上一切','精通「雪见之壁」防御术、战术布局、快速反应','在团队中找到自己的定位，保护千羽，证明均衡型忍者的价值','他是风见苍的二弟子；他是千羽的挚友；他与第三名焰子是搭档','雪见族后裔，天生查克拉控制精准，却因缺乏爆发力而被认为平庸，风见苍让他明白稳定也是一种力量','台词简洁准确，常用陈述句，语气平稳','「数据显示」「我可以掩护」「相信你的直觉」','一个理性冷静的战术型忍者，在团队中找到平衡，从执行者到决策者的转变。','',''),
(146,1,'CHAR_004','焰子',NULL,'女','16岁',NULL,'急躁冲动，容易情绪化，但在保护同伴时能爆发出惊人力量，对风见苍又爱又恨','配角（学生）',NULL,1,'2026-11-02 17:15:07.746718','2026-11-02 17:15:07.746718','毕业班第三名，性格火爆，实力不稳定，风见苍的难题','本剧角色','#4a3b57','毕业班第三席，风见苍的第三弟子','他是风见苍最难教的学生，也是千羽的竞争对手','她站在冲动与成长的边缘，既想证明自己又怕伤害同伴','短发凌乱，眼睛圆大，皮肤偏红，常穿红色忍服配黑色手套，佩戴焰子族徽记','身材矮小但肌肉结实，爆发力强，手脚灵活','红色忍服上衣，黑色短裤，黑色长靴，黑色手套，腰间挂着火遁忍具，左臂戴着一个红色手环','身体健康，但情绪波动大时常感到胸闷，精神亢奋但易焦虑','第1集起：在考核中因冲动而失误，被风见苍严厉批评；第2集：在风见苍的引导下学会控制情绪，开始稳定输出；第2集：在生死对决中保护千羽和雪见，完成蜕变','站立于训练场边缘，双手叉腰，一脸不服气；突破时单腿跺地，双手高举，火焰环绕；决战时单膝跪地，一手护住千羽，一手握拳','我要证明给他们看，我不只是脾气大','精通「焰子之火」爆发术、快速攻击、情绪转化','控制情绪，稳定实力，保护同伴，证明自己的价值','她是风见苍的第三弟子；她是千羽的竞争对手兼朋友；她与第四名冰见是冤家','焰子族后裔，天生查克拉爆发力强，却因情绪失控而实力波动，风见苍让她明白愤怒可以转化为力量','台词短促有力，常用感叹句，语气激烈','「看招！」「别挡路！」「我会保护你们的」','一个性格火爆却内心柔软的女孩，在冲动与成长之间寻找平衡，从破坏者到保护者的转变。','',''),
(147,1,'CHAR_005','冰见',NULL,'男','17岁',NULL,'沉默寡言，观察力极强，习惯独自行动，对风见苍抱有隐秘的信任','配角（学生）',NULL,1,'2026-11-02 17:15:07.746718','2026-11-02 17:15:07.746718','毕业班第四名，性格孤僻，实力深藏不露，风见苍的隐藏王牌','本剧角色','#524033','毕业班第四席，风见苍的第四弟子','他是风见苍最神秘的学生，也是雪见的搭档','他站在孤独与连接的边界，既想保持距离又渴望被理解','短发平头，眼睛深邃，皮肤苍白，常穿蓝色忍服配黑色围巾，佩戴冰见族徽记','身材高挑修长，动作轻盈，气息寒冷','蓝色忍服上衣，黑色长裤，黑色围巾，黑色忍者鞋，腰间挂着冰遁忍具，右手戴着一枚蓝色戒指','身体健康，但体温偏低，精神内敛，善于隐藏情绪','第1集起：在考核中保持低调，暗中观察其他学生；第2集：在风见苍的引导下开始信任团队，展现真实实力；第2集：在生死对决中发挥关键作用，扭转局势','站立于训练场角落，双手插兜，目光游离；突破时单腿站立，双手缓缓抬起，寒气弥漫；决战时单膝跪地，一手结印，一手指向敌人','我不需要被理解，但我希望有人看到我的努力','精通「冰见之寂」控制术、隐蔽行动、环境利用','找到归属感，展现真实自我，成为团队不可或缺的一部分','他是风见苍的第四弟子；他是雪见的搭档；他与焰子是冤家','冰见族后裔，天生查克拉控制精密，却因性格孤僻而被忽视，风见苍让他明白孤独不是缺陷而是优势','台词极少，常用短句，语气低沉','「我在」「够了」「结束」','一个孤僻却深藏不露的忍者，在孤独与连接之间找到平衡，从旁观者到参与者的转变。','',''),
(148,1,'CHAR_006','岚音',NULL,'女','15岁',NULL,'乐观开朗，不服输，喜欢尝试新事物，对风见苍充满崇拜','配角（学生）',NULL,1,'2026-11-02 17:15:07.746718','2026-11-02 17:15:07.746718','毕业班第五名，年纪最小，天赋平平但韧性极强，风见苍的奇迹','本剧角色','#334a45','毕业班第五席，风见苍的第五弟子','他是风见苍最年轻的学生，也是班级的开心果','她站在平凡与非凡的交界处，既想证明自己又怕被落下','长发马尾，眼睛明亮，皮肤健康，常穿绿色忍服配黄色围巾，佩戴岚音族徽记','身材娇小，动作敏捷，耐力强','绿色忍服上衣，黄色短裤，黄色围巾，绿色忍者鞋，腰间挂着医疗忍具，左耳戴着一个绿色铃铛','身体健康，但体力较弱，精神饱满，充满正能量','第1集起：在考核中努力追赶，不断尝试新战术；第2集：在风见苍的指导下学会持久战，成为团队的后盾；第2集：在生死对决中发挥医疗能力，拯救多名同伴','站立于训练场中央，双手握拳，满脸笑容；突破时单腿跳跃，双手挥动，绿色查克拉环绕；决战时单膝跪地，一手治疗同伴，一手握拳','我还差得远，但我不会放弃','精通「岚音之风」辅助术、治疗术、持久战','坚持到底，成为团队的后盾，证明平凡也可以创造奇迹','她是风见苍的第五弟子；她是千羽的妹妹般存在；她与雪见是搭档','岚音族后裔，天生查克拉亲和度低，却因韧性极强而被风见苍看中，他让她明白坚持比天赋更重要','台词活泼，常用疑问句和感叹句，语气轻快','「再试一次！」「我可以的」「老师，加油」','一个年纪最小却韧性极强的女孩，在平凡中创造奇迹，从追赶者到支撑者的转变。','',''),
(149,1,'CHAR_007','霜华',NULL,'男','18岁',NULL,'沉稳内敛，经验丰富，善于保护同伴，对风见苍怀有敬意','配角（学生）',NULL,1,'2026-11-02 17:15:07.746718','2026-11-02 17:15:07.746718','毕业班第六名，年纪最大，实力最强却最谨慎，风见苍的定海神针','本剧角色','#3a4a52','毕业班第六席，风见苍的第六弟子','他是风见苍最年长的学生，也是班级的守护者','他站在经验与创新的边界，既想保守稳妥又渴望突破','短发整齐，眼睛温和，皮肤健康，常穿棕色忍服配黑色腰带，佩戴霜华族徽记','身材高大健壮，力量强，动作沉稳','棕色忍服上衣，黑色长裤，黑色腰带，棕色忍者鞋，腰间挂着防御忍具，右臂戴着一个棕色臂章','身体健康，但年龄稍大反应稍慢，精神稳定，善于安抚他人','第1集起：在考核中承担防御职责，保护其他学生；第2集：在风见苍的指导下学会主动进攻，突破保守思维；第2集：在生死对决中承担主攻角色，带领团队胜利','站立于训练场后方，双手背在身后，目光温和；突破时单腿站稳，双手挥拳，棕色查克拉环绕；决战时单膝跪地，一手防御，一手攻击','经验是财富，但不是枷锁','精通「霜华之盾」防御术、力量爆发、团队协调','突破自我，带领团队胜利，证明老将也能焕发新生','他是风见苍的第六弟子；他是焰子的保护者；他与冰见是对手','霜华族后裔，天生查克拉力量强大，却因年龄较大而被认为过时，风见苍让他明白经验可以转化为智慧','台词沉稳，常用陈述句，语气温和','「放心」「我来」「我们在一起」','一个年纪最大却实力最强的忍者，在经验与突破之间找到平衡，从守护者到领路者的转变。','',''),
(150,1,'CHAR_008','雾影',NULL,'女','16岁',NULL,'机智灵活，善于思考，喜欢用策略取胜，对风见苍充满好奇','配角（学生）',NULL,1,'2026-11-02 17:15:07.746718','2026-11-02 17:15:07.746718','毕业班第七名，实力最弱却最聪明，风见苍的智囊','本剧角色','#2f3a4a','毕业班第七席，风见苍的第七弟子','他是风见苍最聪明的学生，也是班级的智囊','她站在智慧与实力的边界，既想用脑取胜又怕被看轻','短发微卷，眼睛灵动，皮肤白皙，常穿紫色忍服配黑色蝴蝶结，佩戴雾影族徽记','身材纤细，动作灵活，思维敏捷','紫色忍服上衣，黑色短裙，黑色蝴蝶结，紫色忍者鞋，腰间挂着策略忍具，左腕戴着一个紫色手链','身体健康，但体力较弱，精神活跃，善于创新','第1集起：在考核中运用策略弥补实力差距；第2集：在风见苍的指导下学会结合实力与策略，成为团队核心；第2集：在生死对决中制定关键策略，带领团队逆转','站立于训练场中央，双手托腮，眼神灵动；突破时单腿站立，双手快速结印，紫色查克拉环绕；决战时单膝跪地，一手思考，一手指挥','聪明不是万能的，但能让我走得更远','精通「雾影之谋」策略术、幻术、情报收集','运用智慧弥补实力，成为团队的核心，证明脑力也是实力','她是风见苍的第七弟子；她是千羽的智囊；她与岚音是好友','雾影族后裔，天生查克拉控制灵活，却因实力较弱而被低估，风见苍让她明白智慧可以弥补一切','台词机智，常用反问句和设问句，语气灵动','「你猜呢？」「有办法了」「看我的」','一个实力最弱却最聪明的女孩，在智慧与实力之间找到平衡，从智囊到核心的转变。','',''),
(151,1,'CHAR_009','风见苍的导师',NULL,'男','55岁',NULL,'严厉但慈爱，注重传统，对风见苍的激进方法既担忧又支持','配角',NULL,1,'2026-11-02 17:15:07.746718','2026-11-02 17:15:07.746718','前忍校首席教师，风见苍的引路人，已退休','本剧角色','#3b4a63','前忍校首席教师，已退休','他是风见苍的导师，也是唯一知道苍过去失败经历的人','他站在传统与创新的边界，既想维护规矩又希望看到新一代成长','白发整齐，眼睛深邃，皮肤健康，常穿白色长袍配黑色腰带，佩戴旧式教师木牌','身材高大，略显佝偻，但步伐稳健','白色长袍，黑色腰带，白色长靴，腰间挂着旧式忍具包，左臂戴着一个白色袖章','身体健康，但年老体衰，精神依然敏锐，善于洞察人心','第1集起：在忍校旁观考核，暗中观察风见苍的表现；第2集：在关键时刻给出指导，帮助风见苍解决难题；第2集：在生死对决中提供支援，见证学生的蜕变','站立于忍校高处，双手背在身后，目光深远；指导时单腿站立，双手结印；支援时单膝跪地，一手支援，一手观察','我老了，但我的心还年轻','精通「传统禁术」、查克拉理论、战术指导','传承经验，见证新一代的成长，证明传统仍有价值','他是风见苍的导师；他是忍校校长的旧友；他是千羽的曾祖父','曾是忍校最杰出的教师，因一次改革失败而退休，风见苍的出现让他看到了希望','台词温和，常用引经据典，语气深远','「记住」「传承」「未来」','一个严厉但慈爱的导师，在传统与创新之间寻找平衡，从旁观者到支持者的转变。','',''),
(152,1,'CHAR_010','忍校校长',NULL,'男','60岁',NULL,'威严果断，注重结果，对风见苍既信任又警惕','配角',NULL,1,'2026-11-02 17:15:07.746718','2026-11-02 17:15:07.746718','忍校最高管理者，支持风见苍的末位淘汰制','本剧角色','#35435a','忍校校长','他是风见苍的上司，也是千羽的祖父','他站在权力与理想的边界，既想看到学校崛起又怕失去控制','白发整齐，眼睛锐利，皮肤健康，常穿黑色长袍配金色腰带，佩戴校长徽章','身材高大，挺拔，气势威严','黑色长袍，金色腰带，黑色长靴，腰间挂着校长忍具包，右臂戴着一个金色袖章','身体健康，精神饱满，善于决断','第1集起：在忍校办公室审阅报告，支持风见苍的计划；第2集：在训练场旁观，对风见苍的方法表示认可；第2集：在生死对决中宣布规则，见证学生的蜕变','站立于办公室中央，双手撑在桌沿，目光锐利；旁观时单腿站立，双手抱胸；宣布时单膝跪地，一手高举，一手挥动','我赌的是未来，不是过去','精通「行政决策」、查克拉资源调配、危机管理','推动忍校崛起，证明末位淘汰制的有效性，维护学校声誉','他是风见苍的上司；他是千羽的祖父；他是风见苍导师的旧友','曾是普通忍者，通过努力成为校长，深知忍者的残酷，因此支持风见苍的激进方法','台词威严，常用命令句，语气果断','「执行」「结果」「未来」','一个威严果断的校长，在权力与理想之间寻找平衡，从观察者到推动者的转变。','',''),
(153,5,'CHAR_001','李宝明',NULL,'男','24',NULL,'温和而敏锐，习惯在学员结印卡壳时轻敲对方手腕而非呵斥','主角',NULL,1,'2026-11-02 17:56:39.663593','2026-11-02 17:56:39.663593','木叶忍者学院新任基础忍术讲师','本剧角色','#3b4a63','木叶忍者学院·基础忍术讲师','学员的授业者，老派讲师的挑战对象，暗部的观察对象','开放接纳，试图以理服人','黑色短发/标准脸型/白皙肤色/面部轮廓分明、佩戴细框眼镜','中等身材、匀称体格','深绿色忍者马甲配黑色长袖、黑色长裤、网状袖口与腿套、黑色高帮鞋、护腕配饰','健康，偶尔因连续备课出现轻微颈椎不适','克制中带着好奇，对核心学员有超越师生的关注','清醒，保持教育者理智，但在课后走廊会短暂失神','第1集起：正在整理教案，思考如何将心理学融入结印教学；第1集：首堂忍术课展现“心流陷阱”，震惊全场，但面临下周考核压力','站立，双手撑在讲台边缘，微微低头看向学员','“只要找到正确的呼吸节奏，忍术就不是天赋，而是习惯”','将现代心理学转化为忍术引导技巧，擅长观察微表情','证明创新教学法的可行性，建立权威','与核心学员（假设名：樱井桃）有潜在情感羁绊，与老派讲师（假设名：千代宗）有学术冲突','穿越者，带着现代教育思维进入传统忍界，首战即面对质疑','“别急，感受气流的走向”、“结印只是结果，心流才是过程”','用智慧降维打击，打破传统认知，建立新秩序',''),
(154,5,'CHAR_002','樱井桃',NULL,'女','15',NULL,'倔强且敏感，擅长在压力下爆发潜能，面对李宝明时眼神会不自觉软化','核心学员',NULL,1,'2026-11-02 17:56:39.663593','2026-11-03 14:51:23.021309','木叶忍者学院·精英班学员','本剧角色','#35435a','木叶忍者学院·学员','李宝明的得意门生，暗部眼中的“变数”','信任中带着依赖，渴望被理解','棕褐色双丸子头发型/精致小巧的五官/白皙透亮的肤色/清秀甜美面带微笑','高挑纤细且比例匀称的模特体型','红白配色改良式无袖中式连体衣/白色红纹及膝长袜搭配红白木屐/无额外发饰与配饰','体能充沛但易疲劳，突破时会出现轻微手抖','暗恋李宝明，却在课堂上拼命维持距离','紧张，渴望认可又害怕被看穿','第1-2集：在基础训练场进行高难度结印练习，汗水浸湿鬓角；第1集：突破瓶颈，但失控暴露，需在考核中稳定控制','单膝跪地，双手结印至一半停滞，抬头看向李宝明','“老师，我感觉到了，但抓不住”','擅长雷遁系忍术，爆发力强但控制力弱','在李宝明指导下突破瓶颈，成为王牌班核心','与李宝明有情感张力，与老派讲师千代宗有竞争关系','出身普通家庭，因天赋异禀被选入精英班，却受困于传统教学瓶颈','“李老师，这次真的可以了吗？”、“别看我，我在集中精神”','在克制中释放潜能，在依赖中保持独立',''),
(155,5,'CHAR_003','千代宗',NULL,'男','45',NULL,'固执且权威，习惯用“血统”和“经验”压人，对李宝明充满不屑','老派讲师',NULL,1,'2026-11-02 17:56:39.663593','2026-11-03 14:53:10.973995','木叶忍者学院·资深忍术讲师','本剧角色','#3f4652','木叶忍者学院·资深讲师','李宝明的竞争对手，派系领袖','敌意中带着警惕，试图维护传统权威','金色蓬松短发/五官立体轮廓分明/偏小麦色皮肤/左眼有疤痕、神情冷峻','修长挺拔、肌肉线条明显','黑白拼接无袖马甲搭配深色宽松长裤/白色绷带缠绕手腕、腰间黑色护甲/背后佩刀','健康，但因长期高压出现轻微胃溃疡','对李宝明感到威胁，对学员寄予厚望','自负，坚信传统不可动摇','第1-2集：在讲师休息室翻阅李宝明的教案，眉头紧锁；第1集：宣布下周考核，暗示对抗升级，准备高难度陷阱','坐在木质长桌主位，手指敲击桌面，眼神扫过窗外训练场','“野路子，迟早要翻车”','精通土遁系忍术，擅长制定严苛考核标准','在考核中击败李宝明，恢复传统教学地位','与李宝明有学术冲突，与暗部高层有利益关联','传统忍术世家出身，在学院任教二十年，主导派系资源分配','“就凭你这套‘气韵’理论？别把学员的命当儿戏”、“规矩就是规矩，改了规矩，木叶还是木叶吗”','以权威压人，用经验否定创新，维护旧秩序',''),
(156,5,'CHAR_004','暗部监视者',NULL,'男','30',NULL,'沉默且神秘，只露出眼睛和手，通过阴影传递压力','观察员',NULL,1,'2026-11-02 17:56:39.663593','2026-11-03 14:53:23.885120','木叶忍者学院·高塔监视室黑衣身影','本剧角色','#4a3b57','木叶忍者学院·暗部监视者','李宝明的隐形压力源，高层的眼线','中立中带着评估，关注李宝明的“异常”','银白色向上竖立的蓬松长发/立体硬朗的面部轮廓/白皙肤色/额头中央嵌有红色菱形印记、左脸带有黑色纹路','高挑健硕，骨架宽大，肌肉线条紧实','白色高领长款大衣/领口装饰黑色圆形纽扣/手持黑色长杖/黑色露趾凉鞋','健康，长期在阴影中行动导致视力敏锐但畏光','对李宝明感到好奇，对学员的变动感到警惕','冷静，保持距离，随时准备介入','第1-2集：在高塔监视室观察基础训练场，记录李宝明的教学细节；第1集：开始监控李宝明，记录其教学细节，暗示监控升级','坐在沙盘旁，手指轻轻点在沙盘上的李宝明位置','“凡人教忍者？有趣，但危险”','擅长隐匿与观察，能捕捉细微动作变化','确认李宝明的价值或威胁，向高层汇报','与李宝明有监视关系，与高层有汇报关系','来自暗部核心层，负责监控学院潜在变数','“继续观察，不要惊动”、“如果学员出现异常波动，立刻上报”','在阴影中观察，用沉默施加压力，等待时机',''),
(157,5,'CHAR_005','木叶学院高层',NULL,'男','60',NULL,'威严且谨慎，重视学院稳定，对李宝明持观望态度','决策者',NULL,1,'2026-11-02 17:56:39.663593','2026-11-03 14:53:40.143114','木叶忍者学院·院长','本剧角色','#524033','木叶忍者学院·院长','李宝明的上级，派系斗争的仲裁者','中立中带着权衡，试图平衡传统与创新','金色长发/棱角分明的五官/健康小麦色皮肤/额头有漩涡标志护额+面部有猫须状纹路','肌肉发达健硕','无袖深蓝紫色上衣+白色斜跨胸带+深色宽松裤+棕色凉鞋/黑色弯曲头角+额头护额/手臂缠绕绷带+手持红白羽扇武器','健康，但因政务繁忙略显疲态','对李宝明既欣赏又担忧，希望学院繁荣','谨慎，权衡利弊，不愿轻易打破平衡','第1-2集：在院长办公室听取千代宗汇报，审视李宝明的教案','坐在办公桌后，身体微微前倾，手指轻点桌面','“给他一次机会，但别让他走得太远”','精通综合忍术，擅长政治博弈与资源调配','维持学院稳定，确保李宝明成为助力而非威胁','与李宝明有上下级关系，与千代宗有合作关系，与暗部有直接联系','木叶学院创始人之一，现任院长，主导学院发展方向','“创新可以，但根基不能丢”、“学员的成长，就是学院的未来”','以权威平衡派系，用长远眼光审视当下','');
