DROP TABLE IF EXISTS `人物关系`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `人物关系` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `剧id` bigint(20) NOT NULL COMMENT '所属剧',
  `边序` int(11) DEFAULT 0 COMMENT '展示顺序',
  `甲` varchar(50) NOT NULL COMMENT '角色A名',
  `乙` varchar(50) NOT NULL COMMENT '角色B名',
  `类型` varchar(20) DEFAULT NULL COMMENT '羁绊/协作/认可/对立/利用/亲情',
  `关键词` varchar(255) DEFAULT NULL COMMENT '关键词，顿号分隔',
  `说明` text DEFAULT NULL COMMENT '关系说明（可分段）',
  `创建时间` datetime(6) DEFAULT NULL,
  `更新时间` datetime(6) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_人物关系_剧id` (`剧id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='人物关系网边表（/script/character 关系网视图）';
