--
-- Table structure for table `分镜`
--

DROP TABLE IF EXISTS `分镜`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `分镜` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '行主键',
  `剧id` bigint(20) NOT NULL COMMENT '所属剧',
  `集号` int(11) NOT NULL COMMENT '所属集',
  `镜号` varchar(20) NOT NULL COMMENT '镜号，如 SH001',
  `场次` varchar(100) NOT NULL COMMENT '所属场次，如 第一场 · 教室（日）',
  `景别` varchar(20) DEFAULT NULL COMMENT '特写/近景/中景/全景等',
  `运镜` varchar(50) DEFAULT NULL COMMENT '运镜描述，如 推/拉/摇/跟',
  `画面` text NOT NULL COMMENT '画面描述',
  `台词` text DEFAULT NULL COMMENT '本镜台词，无台词留空',
  `时长` varchar(16) DEFAULT NULL COMMENT '单镜时长，如 3s',
  `首帧url` varchar(512) DEFAULT NULL COMMENT '首帧参考图',
  `尾帧url` varchar(512) DEFAULT NULL COMMENT '尾帧参考图',
  `视频状态` varchar(16) NOT NULL DEFAULT '待生成' COMMENT '待生成/生成中/已生成',
  `生成方式` varchar(50) DEFAULT NULL COMMENT '本镜选用的生成方式',
  `生成提示词` text DEFAULT NULL COMMENT '本镜出视频的正向提示词',
  `排序` int(11) NOT NULL DEFAULT 0,
  `创建时间` datetime(6) NOT NULL DEFAULT current_timestamp(6) COMMENT '创建时间',
  `更新时间` datetime(6) NOT NULL DEFAULT current_timestamp(6) ON UPDATE current_timestamp(6) COMMENT '最后更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_分镜_剧集镜号` (`剧id`,`集号`,`镜号`) USING BTREE,
  KEY `idx_分镜_视频状态` (`剧id`,`集号`,`视频状态`) USING BTREE,
  CONSTRAINT `fk_分镜_剧id` FOREIGN KEY (`剧id`) REFERENCES `剧` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=20 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='分镜行：场次/景别/运镜/画面/台词/时长/首尾帧/视频状态';
/*!40101 SET character_set_client = @saved_cs_client */;

