/*!40000 ALTER TABLE `分镜` DISABLE KEYS */;
INSERT INTO `分镜` VALUES
(14,5,1,'SH001','1-1','全景','Static Shot','阳光透过树叶洒在泥地上，李宝明站在讲台前，眼神扫过台下。台下樱井桃坐在第一排高马尾微晃，千代宗抱臂站在角落冷笑，学员群体姿态各异。','千代宗（抱臂）：李讲师，这就是你所谓的“气韵平衡”？我看不过是用心理暗示蒙混过关。','15s',NULL,NULL,'已生成','参考主体','subject_definitions:\n<Subject 1> 是 <Picture 1> 中的女孩，其面部特征、发型、服装与整体外观均取自 <Picture 1>。\n<Picture 1> 是目标视频的唯一视觉参考源，定义 <Subject 1> 的形象锚点。\n\nsummary:\n[reference generation] 目标视频展示 <Subject 1> 在舞蹈场景中表演。<Picture 1> 作为 <Subject 1> 的外观基准，确保角色形象与参考图完全一致。\n\nretention_analysis:\n<Subject 1> (appears in [Shot 1]): fully_preserved - 女孩的面部特征、发型、服装及整体外观均严格遵循 <Picture 1> 的视觉信息。\n<Picture 1> ([Shot 1] reference anchor): fully_preserved - 作为角色外观的唯一来源，其视觉特征在目标视频中完整保留。\n\ndetailed_description:\n目标视频采用高清写实风格，光线柔和均匀。\n[Shot 1] 中景固定镜头，<Subject 1> 位于画面中心，背景为简洁的纯色或虚化室内环境。女孩身着 <Picture 1> 中的服装，面部表情专注且富有感染力。随着音乐节奏，<Subject 1> 开始流畅的舞蹈动作：双臂优雅地抬起并展开，手腕灵活转动，身体跟随旋律轻轻摇摆，重心在双脚间自然切换。镜头保持静止，聚焦于 <Subject 1> 的上半身动作细节与面部表情变化，捕捉其舞蹈时的动态美感与肢体张力。\n\noverall_soundscape:\n轻微的室内环境底噪，伴随舞蹈动作产生的衣物摩擦声。\n\nnon_diegetic_music:\nN/A',0,'2026-11-03 17:44:44.490359','2026-11-03 17:44:44.490359'),
(15,5,1,'SH002','1-1','中景','Push In','李宝明微笑看向千代宗，随后转身示意。樱井桃起身，汗水浸湿鬓角，手微颤抖地走向场地中央木桩旁。','李宝明（微笑）：千代老师，规矩是死的，人是活的。请樱井桃同学上前演示。','12s',NULL,NULL,'待生成','','',1,'2026-11-03 17:44:44.490359','2026-11-03 17:44:44.490359'),
(16,5,1,'SH003','1-1','近景','Tracking Shot','李宝明走近樱井桃，轻敲其手腕节奏舒缓。樱井桃闭眼感受，眼神骤变，周身蓝色/白色雷遁查克拉隐隐闪烁，肌肉线条紧绷，结印动作快至留下残影，雷光爆发，周围树木震颤，学员神情从轻视转为震惊。','樱井桃（低声）：李老师，我感觉到了，但抓不住。李宝明（走近）：别急。感受气流的走向，结印只是结果，心流才是过程。樱井桃（闭眼）：气……在流动。','15s',NULL,NULL,'待生成','','',2,'2026-11-03 17:44:44.490359','2026-11-03 17:44:44.490359'),
(17,5,1,'SH004','1-1','中景','Shake Slightly','樱井桃身体踉跄，雷光失控差点击中木桩，李宝明伸手扶住她。千代宗皱眉，眼中闪过阴狠，转身离去时回头。','千代宗（皱眉）：有意思，但这只是爆发，控制呢？樱井桃（睁眼）：李老师，我……停不下来了！李宝明（伸手扶住）：很好，失败是复盘的开始。记住这种感觉，下周考核，你会用得上。千代宗（回头）：下周考核，我会亲自出题。让我们看看你的“野路子”能撑多久。','15s',NULL,NULL,'待生成','','',3,'2026-11-03 17:44:44.490359','2026-11-03 17:44:44.490359'),
(18,5,1,'SH005','1-2','全景','Static Shot','昏暗高塔监视室内，巨大木叶全景沙盘散发冷光。几名黑衣人站在阴影中，暗部监视者手指轻敲沙盘边缘，眼神锐利。','（无）','10s',NULL,NULL,'待生成','','',4,'2026-11-03 17:44:44.490359','2026-11-03 17:44:44.490359'),
(19,5,1,'SH006','1-2','特写','Zoom In','暗部监视者拿起深色记录板，在“李宝明”名字后重重画圈。阴影中另一只手指轻敲桌面，暗示监控升级。','暗部监视者（低语）：凡人教忍者？有趣，但危险。暗部监视者（轻声）：继续观察，不要惊动。如果学员出现异常波动，立刻上报。','12s',NULL,NULL,'待生成','','',5,'2026-11-03 17:44:44.490359','2026-11-03 17:44:44.490359');
/*!40000 ALTER TABLE `分镜` ENABLE KEYS */;
UNLOCK TABLES;

