INSERT INTO `分集` VALUES
(33,5,1,'首课惊魂：心流陷阱','李宝明首堂忍术课面对千代宗的质疑与学员的轻视，利用心理诱导技巧让最强学员樱井桃在结印时失控破防，展现出“野路子”教学法的惊人成效，震惊全场，但暗部在高塔开始记录这一异常波动。','被老派讲师当众羞辱为“凡人教忍者”，李宝明反手抛出一个心理陷阱，看谁能接得住？','已完成','2026-11-02 12:58:30.603232','2026-11-02 12:58:30.603232','第一幕 · 建置',1,1,4,822,2800,'千代宗拍桌宣布下周考核，李宝明眼神扫过暗处，暗部监视者手指轻敲沙盘，暗示监控升级。','别急，感受气流的走向；结印只是结果，心流才是过程。','李宝明、樱井桃、千代宗、暗部监视者',''),
(34,5,2,'王牌逆袭：实战碾压','面对千代宗设计的针对性考核陷阱，李宝明引导樱井桃克服心理障碍，在实战中利用“失败-复盘”机制完成逆转，王牌班级以绝对优势碾压传统精英班，确立学院新秩序，课后走廊两人情感微妙升温，留下开放式甜蜜结尾。','考核开始，千代宗故意设置高难度连招，李宝明如何让樱井桃在绝境中突破瓶颈？','已完成','2026-11-02 12:58:30.603232','2026-11-02 12:58:30.603232','第二幕 · 对抗',0,0,5,1457,3000,'考核结束，李宝明晋升首席讲师，课后黄昏走廊，樱井桃欲言又止，李宝明以“下课铃响”打断，转身离去，余韵悠长。','规矩就是规矩，但这次，规矩变了；李老师，这次真的可以了吗？','李宝明、樱井桃、千代宗、木叶学院高层','');
/*!40000 ALTER TABLE `分集` ENABLE KEYS */;
UNLOCK TABLES;

