/*!40000 ALTER TABLE `剧` DISABLE KEYS */;
INSERT INTO `剧` VALUES
(1,1,'火影之禁术教师',24,'热血','忍校教师用末位淘汰制带毕业班，师生羁绊群像剧，验证剧本创作链路用','原创',0,0,'2026-10-29 17:33:03.822360','2026-10-29 17:33:04.399128',NULL,'D:/产物/火影之禁术教师','创作中'),
(3,1,'炼金术师在火影当老师',2,'同人','李宝明本是精通炼金术的学者，意外穿越至火影忍者世界，化身为学校教师。他利用现代炼金知识在忍界掀起波澜，却在日常教学中与学生产生微妙情愫。当古老的炼金公式遇上神秘的查克拉，当理性的科学思维碰撞感性的忍者世界，一段跨越次元与身份的爱恨纠葛悄然展开。他不仅要解开穿越之谜，还要在师生界限与忍者法则的夹缝中，守护这份禁忌而炽热的感情。','原创',0,0,'2026-10-30 14:13:35.423277','2026-10-30 14:13:35.556570',NULL,NULL,'创作中'),
(4,1,'火影之炼金术师与别天神教师',2,'同人','李宝明与王哲意外穿越至火影忍者世界，李宝明获系统加持，掌握炼金术与初级别天神，王哲则习得基础忍术。为隐匿身份并融入木叶，李宝明选择成为一名忍者学校的老师。课堂上，他看似温和，实则暗中运用别天神观察学生心性，用炼金术制造新奇道具辅助教学，与性格迥异的学生们从摩擦不断到互相欣赏。王哲作为助教，在忍术指导中展现不凡天赋，成为学生心中的“酷学长”。随着剧情推进，李宝明不仅要应对日常教学的琐碎，更在关键时刻以炼金术解决危机，用别天神化解班级内部的矛盾与潜在威胁。观众将见证一位拥有超能力的“神仙老师”如何重塑这群未来忍者的成长轨迹，以及他在师生互动中逐渐揭开木叶表象下的深层秘密，期待下一集看老师如何带领学生完成第一次实战考核。','原创',0,0,'2026-10-30 16:00:07.939132','2026-10-30 16:00:08.346670',NULL,NULL,'创作中'),
(5,1,'火影：我在学校教忍术',2,'同人','李宝明意外穿越至火影忍者世界，身份从普通人变成了学院里一名不起眼的忍术讲师。面对一群天赋各异、性格鲜明的忍者学员，他利用现代教育思维与传统忍术结合的独特教学法，迅速在学术界崭露头角。然而，真正的麻烦源于他与学生之间逐渐升温的情感线——在严谨的师生界限与炽热的爱意之间，他不仅要应对暗部监视和学院派系斗争，更要解开这段关系背后的命运羁绊。当课堂上的默契转化为生活中的心跳加速，他该如何在守护学生成长与拥抱个人幸福间找到平衡？这种“师配生”的禁忌感与热血修炼的日常反差，让观众既期待他的教学金句频出，又迫不及待想看两人如何在忍界规则下甜蜜又纠结地推进关系，究竟是谁先捅破那层窗户纸？','原创',0,0,'2026-11-02 09:31:04.993391','2026-11-02 09:31:05.511835',NULL,NULL,'创作中');
/*!40000 ALTER TABLE `剧` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `剧本`
--

DROP TABLE IF EXISTS `剧本`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `剧本` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '行主键',
  `剧id` bigint(20) NOT NULL COMMENT '所属剧',
  `集号` int(11) NOT NULL COMMENT '集号',
  `版本类型` varchar(10) NOT NULL DEFAULT '创作版' COMMENT '创作版（创作线可改）/ 定稿版（视频线引用快照，C1）',
  `版本` int(11) NOT NULL DEFAULT 1 COMMENT '同版本类型内的版本号，支持回到创作版重改',
  `标题` varchar(100) DEFAULT NULL COMMENT '集标题',
  `总字数` int(11) NOT NULL DEFAULT 0 COMMENT '总字数；定稿前校验单集 800~5000 字',
  `场次` longtext DEFAULT NULL COMMENT '【已弃用】场次数组JSON（旧设计），2026-11-02 起新数据走 场次 实体表（docs 02 第 12 节）',
  `定稿` tinyint(1) NOT NULL DEFAULT 0 COMMENT '【C1】1=已定稿锁定；解锁需确认且资产/分镜页提示"剧本已变动建议重提取/重拆"',
  `定稿时间` datetime(6) DEFAULT NULL COMMENT '定稿时间',
  `创建时间` datetime(6) NOT NULL DEFAULT current_timestamp(6) COMMENT '创建时间',
  `更新时间` datetime(6) NOT NULL DEFAULT current_timestamp(6) ON UPDATE current_timestamp(6) COMMENT '最后更新时间',
  `正文` text DEFAULT NULL COMMENT '本集正文全文，按场次排，换行分段',
  `能力档案` text DEFAULT NULL COMMENT '键值行文本：所属势力…目前目标 10 键',
  `世界状态` text DEFAULT NULL COMMENT '键值行文本：当前世界…附近动向 11 键',
  `关系网络` text DEFAULT NULL COMMENT '键值行文本：当前主线/预告1/预告2/蝴蝶效应/历史进程/角色记录',
  `记忆回廊` text DEFAULT NULL COMMENT '键值行文本：长期记忆+短期记忆1-6',
  `行动推荐` text DEFAULT NULL COMMENT '行文本，每行 N. 内容',
  `状态` varchar(16) DEFAULT '待复核' COMMENT '待复核/已复核（页面复核语义）',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_剧本_剧集版本` (`剧id`,`集号`,`版本类型`,`版本`) USING BTREE,
  CONSTRAINT `fk_剧本_剧id` FOREIGN KEY (`剧id`) REFERENCES `剧` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='每集剧本（创作版/定稿版分离+版本链）；定稿版是视频线的唯一事实源';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `剧本`
--

LOCK TABLES `剧本` WRITE;
/*!40000 ALTER TABLE `剧本` DISABLE KEYS */;
INSERT INTO `剧本` VALUES
(4,5,2,'创作版',1,'王牌逆袭：实战碾压',1457,'',0,NULL,'2026-11-02 12:23:29.657850','2026-11-02 13:00:22.914507','2-1 · 内 · 木叶忍者学院·讲师休息室 · 日\n出场人物：千代宗、木叶学院高层\n出场道具：木质长桌、热茶、李宝明的教案\n△ 千代宗的手指重重敲击在桌面上，面前的教案被捏出一丝褶皱。\n千代宗（冷笑）：院长，您看看这教案，连查克拉流向都画反了，这叫“创新”？\n木叶学院高层（揉着太阳穴，眼神疲惫）：千代，别急着下结论。李宝明虽然资历浅，但最近三班的出勤率是全院最高的。\n千代宗（嗤笑）：出勤率高有什么用？下周的考核，我会亲自出题。我要看看，他的“野路子”到底能撑多久。\n木叶学院高层（点头）：给他一次机会，但别让他走得太远。记住，我们要的是稳定，不是奇迹。\n千代宗（起身，整理衣领）：明白了，大人。我会让他在下周的实战中，见识一下什么叫“传统”的重量。\n\n2-2 · 外 · 木叶忍者学院·基础训练场 · 日\n出场人物：李宝明、樱井桃、暗部监视者（远处阴影中）\n出场道具：结印靶标、训练用木桩\n△ 阳光透过树叶洒在泥地上，李宝明站在场地中央，袖口卷起，神情温和。\n△ 樱井桃站在前排，高马尾随着她的动作微微晃动，眼神中带着警惕与期待。\n李宝明（轻声）：不要想“结印”，想“呼吸”。把查克拉想象成水流，你只需要打开阀门，而不是用力推水。\n樱井桃（咬唇，额头渗出细汗）：可是……每次到“蛇”印的时候，我就感觉气韵断了。\n李宝明（走近，轻轻敲了一下她的手腕）：别急，感受气流的走向；结印只是结果，心流才是过程。现在，闭上眼睛，听风的声音。\n△ 樱井桃闭上眼，周围的风声似乎变得清晰起来。\n△ 李宝明后退半步，双手结印，动作缓慢而优雅，仿佛在与风对话。\n李宝明（低声引导）：吸气……呼气……让查克拉顺着你的指尖流淌，不要抗拒它的方向。\n樱井桃（眉头紧锁，手指颤抖）：我……我感觉到了，但抓不住。\n李宝明（微微一笑）：那就让它从指缝间溜走，再去追它。\n△ 樱井桃的手指突然加速，结印速度远超以往，最后一印落下时，空气中响起一声清脆的爆鸣。\n△ 一个小型火球凭空出现，精准地击中了远处的木桩，留下一个焦黑的深坑。\n△ 周围的学员们倒吸一口凉气，纷纷投来震惊的目光。\n暗部监视者（在远处树影中，手指轻敲树干，眼神锐利）：凡人教忍者？有趣，但危险。\n\n2-3 · 内 · 木叶忍者学院·讲师休息室 · 日\n出场人物：千代宗、李宝明\n出场道具：茶杯、教案\n△ 千代宗推门而入，直接将一杯热茶放在李宝明面前，杯壁上的水珠滴落在桌上。\n千代宗（语气冰冷）：听说你的学生在昨天创下了结印速度的新纪录？\n李宝明（端起茶杯，抿了一口，神色平静）：千代老师，那只是课堂练习，并非实战。\n千代宗（眯起眼睛）：实战？下周的考核，我会让精英班出列，与你的班级进行对抗。我要看看，你的“心理诱导”在真刀真枪面前，还能不能保住那层窗户纸。\n李宝明（放下茶杯，眼神扫过千代宗身后的阴影）：如果输了，我会主动申请调离基础部。\n千代宗（嘴角勾起一抹弧度）：希望到时候，你还记得今天说的这句话。\n\n2-4 · 外 · 木叶忍者学院·课后走廊 · 黄昏\n出场人物：李宝明、樱井桃\n出场道具：无\n△ 黄昏的光线斜射进走廊，栏杆投下长长的影子。\n△ 李宝明与樱井桃并肩而行，两人之间保持着微妙而安全的距离。\n樱井桃（停下脚步，侧过头，眼神闪烁）：老师，我刚才……是不是做得很好？\n李宝明（轻声）：你找到了属于自己的节奏，这比结果更重要。\n樱井桃（低头，手指无意识地缠绕着发梢）：可是，我总觉得……在那一瞬间，我离你很近。\n△ 李宝明的脚步微微一顿，随即恢复正常，没有回头。\n李宝明（转身，背影挺拔）：下课铃响了，回去休息吧，明天还有更难的训练。\n△ 樱井桃站在原地，看着李宝明离去的方向，嘴角抿成一条直线，眼中却闪过一丝不易察觉的温柔。','所属势力：木叶忍者学院·基础部\n声望影响：初露锋芒，引发老派势力警惕\n阶级：讲师\n评级：B+（潜力A-）\n拥有技能：心理诱导结印法、气流节奏控制\n当前体力：良好\n能量状态：稳定\n健康状态：轻微颈椎不适\n拥有物品：教案、软底忍者靴\n目前目标：在下周考核中证明创新教学法的有效性','当前世界：火影忍者世界·和平时期\n当前日期：第1年春月初二\n当前区域：木叶隐村·忍者学院\n当前环境：明亮暖色调，阳光充足\n当前事件：李宝明首课成功，引发派系关注\n区域布局：训练场、休息室、高塔监视室\n区域情报：暗部开始记录李宝明的教学波动\n区域角色：李宝明、樱井桃、千代宗、暗部监视者\n传闻：基础部新讲师用“呼吸法”打破了结印瓶颈\n附近热议：老派讲师与新派讲师的教学理念冲突\n附近动向：下周考核即将开始，各班级紧张备战','当前主线：李宝明 vs 千代宗的教学理念对抗\n预告1：下周考核中，李宝明带领班级逆转局势\n预告2：暗部介入，监视升级\n蝴蝶效应：樱井桃的突破引发其他学员对李宝明的关注\n历史进程：传统教学法面临挑战\n角色记录：李宝明首次展示“心流”教学法','长期记忆：李宝明穿越至火影世界，成为忍者学院讲师\n短期记忆1：首课成功，樱井桃突破瓶颈，千代宗宣布考核\n短期记忆2：无\n短期记忆3：无\n短期记忆4：无\n短期记忆5：无\n短期记忆6：无','1. 准备下周考核的战术方案，重点针对千代宗的“传统”连招\n2. 与樱井桃进行课后单独训练，巩固其“心流”状态\n3. 观察暗部监视者的动向，调整教学节奏以避免过度曝光','待复核'),
(5,5,1,'创作版',1,'首课惊魂：心流陷阱',822,'',0,NULL,'2026-11-02 12:58:30.278475','2026-11-02 13:00:22.914507','1-1 · 内 · 木叶忍者学院·基础训练场 · 日\n出场人物：李宝明、樱井桃、千代宗\n出场道具：教案、结印辅助木桩\n△ 阳光透过树叶洒在泥地上，李宝明站在讲台前，深蓝色衬衫袖口随意卷起，眼神扫过台下。\n△ 台下学员姿态各异，樱井桃坐在第一排，高马尾随着动作微晃，眼神倔强地盯着李宝明。\n△ 千代宗抱臂站在角落，银灰色短发在阳光下刺眼，嘴角挂着不屑的冷笑。\n千代宗（抱臂）：李讲师，这就是你所谓的“气韵平衡”？我看不过是用心理暗示蒙混过关。\n李宝明（微笑）：千代老师，规矩是死的，人是活的。请樱井桃同学上前演示。\n△ 樱井桃起身，走到场地中央，汗水浸湿了鬓角，手微微颤抖。\n樱井桃（低声）：李老师，我感觉到了，但抓不住。\n李宝明（走近）：别急。感受气流的走向，结印只是结果，心流才是过程。\n△ 李宝明轻轻敲击樱井桃的手腕，节奏舒缓，引导她的呼吸。\n樱井桃（闭眼）：气……在流动。\n△ 樱井桃眼神骤变，周身雷光隐隐闪烁，肌肉线条紧绷，爆发力瞬间达到峰值。\n△ 结印动作快到留下残影，雷遁查克拉如风暴般爆发，周围树木轻轻震颤。\n△ 全场寂静，学员们的眼神从轻视转为震惊。\n千代宗（皱眉）：有意思，但这只是爆发，控制呢？\n樱井桃（睁眼）：李老师，我……停不下来了！\n△ 樱井桃身体踉跄，雷光失控，差点击中旁边的木桩。\n李宝明（伸手扶住）：很好，失败是复盘的开始。记住这种感觉，下周考核，你会用得上。\n△ 千代宗眼中闪过一丝阴狠，转身离去。\n千代宗（回头）：下周考核，我会亲自出题。让我们看看你的“野路子”能撑多久。\n\n1-2 · 内 · 木叶忍者学院·高塔监视室 · 日\n出场人物：暗部监视者\n出场道具：木叶全景沙盘、记录板\n△ 昏暗房间中，巨大的沙盘散发着冷光，几名黑衣人站在阴影里。\n△ 暗部监视者手指轻敲沙盘边缘，眼神锐利如刀。\n暗部监视者（低语）：凡人教忍者？有趣，但危险。\n△ 他拿起记录板，在“李宝明”名字后重重画了一个圈。\n暗部监视者（轻声）：继续观察，不要惊动。如果学员出现异常波动，立刻上报。\n△ 阴影中，另一只手指轻轻敲了敲桌面，暗示监控升级。','所属势力：木叶忍者学院\n声望影响：初露锋芒，受到老派质疑\n阶级：讲师\n评级：待定\n拥有技能：心理诱导、呼吸节奏调整、微表情观察\n当前体力：轻微颈椎不适，但精神饱满\n能量状态：查克拉稳定，无异常\n健康状态：健康，偶尔疲劳\n拥有物品：教案、结印辅助木桩\n目前目标：证明创新教学法可行性，通过下周考核','当前世界：火影忍者世界·木叶隐村\n当前日期：第1年春月初一\n当前区域：木叶忍者学院\n当前环境：和平时期，日常教学\n当前事件：李宝明首堂忍术课，展现“心流陷阱”\n区域布局：基础训练场、高塔监视室、讲师休息室\n区域情报：李宝明教学法引发争议，千代宗宣布下周考核\n区域角色：李宝明、樱井桃、千代宗、暗部监视者\n传闻：据传新讲师李宝明用“气韵平衡”让最强学员失控\n附近热议：学员们在讨论李宝明的“野路子”\n附近动向：千代宗在准备考核题目，暗部开始监控李宝明','当前主线：李宝明用创新教学法对抗传统权威\n预告1：下周考核，千代宗设置高难度陷阱\n预告2：暗部监控升级，李宝明面临更大压力\n蝴蝶效应：樱井桃突破瓶颈，成为王牌班核心\n历史进程：李宝明教学法引发学院内部派系斗争\n角色记录：李宝明与樱井桃建立初步信任，与千代宗形成对立','长期记忆：李宝明穿越成火影学院讲师，用现代心理学降维打击传统忍术教学\n短期记忆1：李宝明用心理诱导让樱井桃失控突破，震惊全场\n短期记忆2：千代宗宣布下周考核，暗示对抗升级\n短期记忆3：暗部开始监控李宝明，记录其教学细节\n短期记忆4：樱井桃突破瓶颈，成为王牌班核心\n短期记忆5：李宝明与千代宗形成对立，引发学院内部派系斗争\n短期记忆6：李宝明用“气韵平衡”理论，引发学员争议','1. 李宝明需在下周考核前，帮助樱井桃稳定控制雷遁爆发\n2. 千代宗将设置高难度连招，李宝明需准备“失败-复盘”机制\n3. 暗部监控升级，李宝明需在教学中保持低调，避免过度暴露','待复核');
