--
-- Table structure for table `参考图`
--

DROP TABLE IF EXISTS `参考图`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `参考图` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `资产行id` bigint(20) NOT NULL COMMENT '所属 美术定装.id',
  `url` varchar(512) NOT NULL COMMENT '图片相对路径，如 上传/xxx.png',
  `标注` varchar(200) DEFAULT NULL COMMENT '图片标注，如 正面定装/侧面/Q版',
  `提示词` text DEFAULT NULL COMMENT '这张图自己的出图/编辑提示词说明',
  `分类` varchar(10) DEFAULT NULL COMMENT '图片分类：人物/场景/道具/服装，默认继承父资产类型',
  `形态` varchar(50) DEFAULT NULL COMMENT '形态标签：同一资产的不同服装/状态，如 常服/受伤',
  `关联人物` varchar(50) DEFAULT NULL COMMENT '关联人物id：人物类型图关联到哪个角色档案（空=按资产id自动匹配）',
  `来源` varchar(10) NOT NULL DEFAULT '生成' COMMENT '生成/上传',
  `状态` varchar(10) NOT NULL DEFAULT '当前' COMMENT '当前/历史（重新生成后旧图转历史）',
  `排序` int(11) NOT NULL DEFAULT 0,
  `创建时间` datetime(6) NOT NULL DEFAULT current_timestamp(6),
  `更新时间` datetime(6) NOT NULL DEFAULT current_timestamp(6) ON UPDATE current_timestamp(6),
  PRIMARY KEY (`id`),
  KEY `idx_参考图_定装` (`资产行id`,`状态`)
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='参考图：一图一行带标注（当前/历史），替代 json 数组';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `参考图`
--

LOCK TABLES `参考图` WRITE;
/*!40000 ALTER TABLE `参考图` DISABLE KEYS */;
