--
-- Table structure for table `场次`
--

DROP TABLE IF EXISTS `场次`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `场次` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `剧id` bigint(20) NOT NULL COMMENT '所属剧',
  `剧本行id` bigint(20) NOT NULL COMMENT '所属剧本行（某剧某集创作版）',
  `场号` varchar(16) NOT NULL COMMENT '场次编号，如 1-1',
  `地点` varchar(100) DEFAULT NULL COMMENT '内/外 · 地点 · 时间',
  `人物` varchar(200) DEFAULT NULL COMMENT '出场人物，顿号分隔',
  `道具` varchar(200) DEFAULT NULL COMMENT '出场道具，顿号分隔',
  `正文` text DEFAULT NULL COMMENT '本场正文，一行一个动作/台词，换行分隔',
  `排序` int(11) NOT NULL DEFAULT 0 COMMENT '场次顺序，数字越小越靠前',
  `创建时间` datetime(6) DEFAULT NULL,
  `更新时间` datetime(6) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_场次_剧本行id` (`剧本行id`)
) ENGINE=InnoDB AUTO_INCREMENT=41 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='每集剧本下的场次与正文（7.5 实体化落地）';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `场次`
--

LOCK TABLES `场次` WRITE;
/*!40000 ALTER TABLE `场次` DISABLE KEYS */;
INSERT INTO `场次` VALUES
(35,5,5,'1-1','内 · 木叶忍者学院·基础训练场 · 日','李宝明、樱井桃、千代宗','教案、结印辅助木桩','△ 阳光透过树叶洒在泥地上，李宝明站在讲台前，深蓝色衬衫袖口随意卷起，眼神扫过台下。\n△ 台下学员姿态各异，樱井桃坐在第一排，高马尾随着动作微晃，眼神倔强地盯着李宝明。\n△ 千代宗抱臂站在角落，银灰色短发在阳光下刺眼，嘴角挂着不屑的冷笑。\n千代宗（抱臂）：李讲师，这就是你所谓的“气韵平衡”？我看不过是用心理暗示蒙混过关。\n李宝明（微笑）：千代老师，规矩是死的，人是活的。请樱井桃同学上前演示。\n△ 樱井桃起身，走到场地中央，汗水浸湿了鬓角，手微微颤抖。\n樱井桃（低声）：李老师，我感觉到了，但抓不住。\n李宝明（走近）：别急。感受气流的走向，结印只是结果，心流才是过程。\n△ 李宝明轻轻敲击樱井桃的手腕，节奏舒缓，引导她的呼吸。\n樱井桃（闭眼）：气……在流动。\n△ 樱井桃眼神骤变，周身雷光隐隐闪烁，肌肉线条紧绷，爆发力瞬间达到峰值。\n△ 结印动作快到留下残影，雷遁查克拉如风暴般爆发，周围树木轻轻震颤。\n△ 全场寂静，学员们的眼神从轻视转为震惊。\n千代宗（皱眉）：有意思，但这只是爆发，控制呢？\n樱井桃（睁眼）：李老师，我……停不下来了！\n△ 樱井桃身体踉跄，雷光失控，差点击中旁边的木桩。\n李宝明（伸手扶住）：很好，失败是复盘的开始。记住这种感觉，下周考核，你会用得上。\n△ 千代宗眼中闪过一丝阴狠，转身离去。\n千代宗（回头）：下周考核，我会亲自出题。让我们看看你的“野路子”能撑多久。',0,'2026-11-02 13:00:22.914507','2026-11-02 13:00:22.914507'),
(36,5,5,'1-2','内 · 木叶忍者学院·高塔监视室 · 日','暗部监视者','木叶全景沙盘、记录板','△ 昏暗房间中，巨大的沙盘散发着冷光，几名黑衣人站在阴影里。\n△ 暗部监视者手指轻敲沙盘边缘，眼神锐利如刀。\n暗部监视者（低语）：凡人教忍者？有趣，但危险。\n△ 他拿起记录板，在“李宝明”名字后重重画了一个圈。\n暗部监视者（轻声）：继续观察，不要惊动。如果学员出现异常波动，立刻上报。\n△ 阴影中，另一只手指轻轻敲了敲桌面，暗示监控升级。',1,'2026-11-02 13:00:22.914507','2026-11-02 13:00:22.914507'),
(37,5,4,'2-1','内 · 木叶忍者学院·讲师休息室 · 日','千代宗、木叶学院高层','木质长桌、热茶、李宝明的教案','△ 千代宗的手指重重敲击在桌面上，面前的教案被捏出一丝褶皱。\n千代宗（冷笑）：院长，您看看这教案，连查克拉流向都画反了，这叫“创新”？\n木叶学院高层（揉着太阳穴，眼神疲惫）：千代，别急着下结论。李宝明虽然资历浅，但最近三班的出勤率是全院最高的。\n千代宗（嗤笑）：出勤率高有什么用？下周的考核，我会亲自出题。我要看看，他的“野路子”到底能撑多久。\n木叶学院高层（点头）：给他一次机会，但别让他走得太远。记住，我们要的是稳定，不是奇迹。\n千代宗（起身，整理衣领）：明白了，大人。我会让他在下周的实战中，见识一下什么叫“传统”的重量。',0,'2026-11-02 13:00:22.914507','2026-11-02 13:00:22.914507'),
(38,5,4,'2-2','外 · 木叶忍者学院·基础训练场 · 日','李宝明、樱井桃、暗部监视者（远处阴影中）','结印靶标、训练用木桩','△ 阳光透过树叶洒在泥地上，李宝明站在场地中央，袖口卷起，神情温和。\n△ 樱井桃站在前排，高马尾随着她的动作微微晃动，眼神中带着警惕与期待。\n李宝明（轻声）：不要想“结印”，想“呼吸”。把查克拉想象成水流，你只需要打开阀门，而不是用力推水。\n樱井桃（咬唇，额头渗出细汗）：可是……每次到“蛇”印的时候，我就感觉气韵断了。\n李宝明（走近，轻轻敲了一下她的手腕）：别急，感受气流的走向；结印只是结果，心流才是过程。现在，闭上眼睛，听风的声音。\n△ 樱井桃闭上眼，周围的风声似乎变得清晰起来。\n△ 李宝明后退半步，双手结印，动作缓慢而优雅，仿佛在与风对话。\n李宝明（低声引导）：吸气……呼气……让查克拉顺着你的指尖流淌，不要抗拒它的方向。\n樱井桃（眉头紧锁，手指颤抖）：我……我感觉到了，但抓不住。\n李宝明（微微一笑）：那就让它从指缝间溜走，再去追它。\n△ 樱井桃的手指突然加速，结印速度远超以往，最后一印落下时，空气中响起一声清脆的爆鸣。\n△ 一个小型火球凭空出现，精准地击中了远处的木桩，留下一个焦黑的深坑。\n△ 周围的学员们倒吸一口凉气，纷纷投来震惊的目光。\n暗部监视者（在远处树影中，手指轻敲树干，眼神锐利）：凡人教忍者？有趣，但危险。',1,'2026-11-02 13:00:22.914507','2026-11-02 13:00:22.914507'),
(39,5,4,'2-3','内 · 木叶忍者学院·讲师休息室 · 日','千代宗、李宝明','茶杯、教案','△ 千代宗推门而入，直接将一杯热茶放在李宝明面前，杯壁上的水珠滴落在桌上。\n千代宗（语气冰冷）：听说你的学生在昨天创下了结印速度的新纪录？\n李宝明（端起茶杯，抿了一口，神色平静）：千代老师，那只是课堂练习，并非实战。\n千代宗（眯起眼睛）：实战？下周的考核，我会让精英班出列，与你的班级进行对抗。我要看看，你的“心理诱导”在真刀真枪面前，还能不能保住那层窗户纸。\n李宝明（放下茶杯，眼神扫过千代宗身后的阴影）：如果输了，我会主动申请调离基础部。\n千代宗（嘴角勾起一抹弧度）：希望到时候，你还记得今天说的这句话。',2,'2026-11-02 13:00:22.914507','2026-11-02 13:00:22.914507'),
(40,5,4,'2-4','外 · 木叶忍者学院·课后走廊 · 黄昏','李宝明、樱井桃','无','△ 黄昏的光线斜射进走廊，栏杆投下长长的影子。\n△ 李宝明与樱井桃并肩而行，两人之间保持着微妙而安全的距离。\n樱井桃（停下脚步，侧过头，眼神闪烁）：老师，我刚才……是不是做得很好？\n李宝明（轻声）：你找到了属于自己的节奏，这比结果更重要。\n樱井桃（低头，手指无意识地缠绕着发梢）：可是，我总觉得……在那一瞬间，我离你很近。\n△ 李宝明的脚步微微一顿，随即恢复正常，没有回头。\n李宝明（转身，背影挺拔）：下课铃响了，回去休息吧，明天还有更难的训练。\n△ 樱井桃站在原地，看着李宝明离去的方向，嘴角抿成一条直线，眼中却闪过一丝不易察觉的温柔。',3,'2026-11-02 13:00:22.914507','2026-11-02 13:00:22.914507');
/*!40000 ALTER TABLE `场次` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `成片`
--

DROP TABLE IF EXISTS `成片`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `成片` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '行主键',
  `剧id` bigint(20) NOT NULL COMMENT '所属剧',
  `集号` int(11) NOT NULL COMMENT '所属集；一集多版本成片',
  `版本` int(11) NOT NULL DEFAULT 1 COMMENT '成片版本号',
  `片段序列` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '时间线：[{镜号,入点,出点,顺序}]（已生成镜头按序串联）' CHECK (json_valid(`片段序列`)),
  `音轨` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '音轨配置：[{类型(配音/BGM/环境音),来源,镜号或全片,音量}]；台词镜头自动配音色（C3）' CHECK (json_valid(`音轨`)),
  `字幕` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '字幕轨：[{镜号,开始,结束,文本}]' CHECK (json_valid(`字幕`)),
  `总时长` decimal(8,2) NOT NULL DEFAULT 0.00 COMMENT '成片总秒数；与剧本目标差 ±20% 时导出前警告',
  `分辨率` varchar(20) NOT NULL DEFAULT '480p' COMMENT '导出分辨率档',
  `码率` varchar(20) DEFAULT NULL COMMENT '导出码率档',
  `导出url` varchar(512) DEFAULT NULL COMMENT '导出的 MP4 路径',
  `AIGC显式标识` varchar(200) NOT NULL DEFAULT '本内容由人工智能生成' COMMENT '【C7】画面角标/片头文案（《人工智能生成合成内容标识办法》2026-09 施行）',
  `AIGC隐式标识` varchar(512) DEFAULT NULL COMMENT '【C7】写入文件元数据的隐式标识串',
  `合成task_id` bigint(20) DEFAULT NULL COMMENT '合成任务（task.id，ffmpeg 队列）',
  `创建时间` datetime(6) NOT NULL DEFAULT current_timestamp(6) COMMENT '创建时间',
  `更新时间` datetime(6) NOT NULL DEFAULT current_timestamp(6) ON UPDATE current_timestamp(6) COMMENT '最后更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_成片_剧集版本` (`剧id`,`集号`,`版本`) USING BTREE,
  CONSTRAINT `fk_成片_剧id` FOREIGN KEY (`剧id`) REFERENCES `剧` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='每集成片；导出强制打 AIGC 标识（C7）';
