CREATE TABLE `技能` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '技能主键',
  `目录名` varchar(255) NOT NULL COMMENT '解压后在 backend/资源/技能/ 下的目录名，不是绝对路径',
  `名称` varchar(255) NOT NULL COMMENT '技能显示名称',
  `简介` text DEFAULT NULL COMMENT '技能说明，上传后可由模型识别再人工改',
  `分类id` bigint(20) NOT NULL COMMENT '所属分类；未分类必须指向「未分类」行，不用空外键',
  `来源` varchar(50) NOT NULL DEFAULT '上传压缩包' COMMENT '来源，固定为「上传压缩包」；第一版不保留扫描磁盘自动建行',
  `原压缩包名` varchar(255) DEFAULT NULL COMMENT '用户上传时的 zip 等文件名，便于对照',
  `创建时间` datetime(6) NOT NULL DEFAULT current_timestamp(6) COMMENT '技能创建时间',
  `更新时间` datetime(6) NOT NULL DEFAULT current_timestamp(6) ON UPDATE current_timestamp(6) COMMENT '技能最后更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_技能_目录名` (`目录名`) USING BTREE,
  KEY `idx_技能_分类id` (`分类id`) USING BTREE,
  CONSTRAINT `fk_技能_分类id` FOREIGN KEY (`分类id`) REFERENCES `技能分类` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=42 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='用户上传压缩包并解压后的技能包；删表行同时删磁盘目录';
