CREATE TABLE `提示词模板` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '提示词模板主键',
  `类型` varchar(50) NOT NULL COMMENT '提示词类型，如 剧本 / 分集 / 人物设定 / 分镜',
  `系统提示词` text DEFAULT NULL COMMENT '该类型使用的完整系统提示词',
  `生成提示词` text DEFAULT NULL COMMENT '该类型使用的完整生成提示词',
  `创建时间` datetime(6) NOT NULL DEFAULT current_timestamp(6) COMMENT '记录创建时间',
  `更新时间` datetime(6) NOT NULL DEFAULT current_timestamp(6) ON UPDATE current_timestamp(6) COMMENT '记录最后更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_提示词模板_类型` (`类型`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=27 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='按类型存放系统提示词与生成提示词，供各页面按类型取用';
/*!40101 SET character_set_client = @saved_cs_client */;

