--
-- Table structure for table `方案`
--

DROP TABLE IF EXISTS `方案`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `方案` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '方案主键',
  `剧id` bigint(20) NOT NULL COMMENT '所属剧；一剧多候选方案',
  `版本号` varchar(50) NOT NULL DEFAULT '方案一' COMMENT '方案版本名，如 方案一/方案二',
  `是否选定` tinyint(1) NOT NULL DEFAULT 0 COMMENT '1=当前选定方案；选定后才能进方案详情与后续步骤。同剧仅一行=1',
  `候选卡` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '/script/plan 方案卡七字段：{标题,故事线,题材,基调,结局,驱动,风险}' CHECK (json_valid(`候选卡`)),
  `时空背景` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '五分区之一：{时空锚,硬规则[],禁忌口径[],场景库[{名称,功能,视觉,预算档}],场景预算}；场景库是视频线资产提取的场景种子' CHECK (json_valid(`时空背景`)),
  `故事线` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '五分区之二：核心冲突键值段' CHECK (json_valid(`故事线`)),
  `爽点矩阵` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '五分区之三：[{集段,类型,设计,强度}]' CHECK (json_valid(`爽点矩阵`)),
  `商业卖点` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '五分区之四：{爽点兑现[],反派压力[]}（观众买单理由/付费卡点版本已删）' CHECK (json_valid(`商业卖点`)),
  `结局设计` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '五分区之五：键值段' CHECK (json_valid(`结局设计`)),
  `基础版本` int(11) NOT NULL DEFAULT 1 COMMENT '【C9】乐观锁版本号：编辑请求带 baseVersion，不匹配返回 409',
  `创建时间` datetime(6) NOT NULL DEFAULT current_timestamp(6) COMMENT '创建时间',
  `更新时间` datetime(6) NOT NULL DEFAULT current_timestamp(6) ON UPDATE current_timestamp(6) COMMENT '最后更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_方案_剧id` (`剧id`) USING BTREE,
  CONSTRAINT `fk_方案_剧id` FOREIGN KEY (`剧id`) REFERENCES `剧` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='创作方案（全剧宪法）；每次分区级保存写一条 方案历史 快照可回滚';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `方案`
