DROP TABLE IF EXISTS `模型配置`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `模型配置` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '配置主键，全表只允许一行',
  `大模型名称` varchar(100) DEFAULT NULL COMMENT '界面展示用的模型称呼',
  `LLM地址` varchar(255) DEFAULT NULL COMMENT '模型配置页填写的 LLM 服务地址（含端口，协议由页面约定，不写死）',
  `LLM密钥` varchar(255) DEFAULT NULL COMMENT 'LLM 接口密钥，本地可空',
  `LLM模型名` varchar(100) DEFAULT NULL COMMENT '请求 LLM 时使用的模型名',
  `ComfyUI地址` varchar(255) DEFAULT NULL COMMENT '模型配置页填写的 ComfyUI 地址',
  `ComfyUI工作流目录` varchar(512) DEFAULT NULL COMMENT 'Comfy 工作流 JSON 所在目录',
  `ComfyUI输出目录` varchar(512) DEFAULT NULL COMMENT 'Comfy 原始输出目录，worker 再拷回 backend/资源/产物/',
  `更新时间` datetime(6) NOT NULL DEFAULT current_timestamp(6) ON UPDATE current_timestamp(6) COMMENT '配置最后更新时间',
  `生图模型` varchar(100) DEFAULT NULL COMMENT '【M5】美术资产生图模型名，如 gpt-image 2；/video/art 页头下拉从这里读',
  `生视频模型` varchar(100) DEFAULT NULL COMMENT '【M5】镜头生成视频模型名；/video/director 生成条从这里读',
  `TTS模型` varchar(100) DEFAULT NULL COMMENT '【M5】音色合成模型名，如 Qwen3 TTS；/video/art 音色区从这里读',
  `价目` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '【M5】积分价目表 JSON，如 {"重提取":50,"TTS":10,"生图":10,"生视频":10,"合成":20}；一处改全局生效' CHECK (json_valid(`价目`)),
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='全平台一份 LLM + ComfyUI 地址配置，最多一行，只更新不删除';
